solution.solution.cpp:
class Engine
{
public:
    void start() { m_running = true; }
    void stop() { m_running = false; }
    bool running() const { return m_running; }

private:
    bool m_running{ false };
};

class Car
{
public:
    void turnKey() { m_engine.start(); }

    bool drive()
    {
        if (!m_engine.running())
        {
            return false;
        }
        m_km += 10;
        return true;
    }

    void park() { m_engine.stop(); }
    int odometer() const { return m_km; }

private:
    Engine m_engine{};
    int m_km{ 0 };
};

unitTests:
TEST("cannot drive before the key is turned") { Car c{}; CHECK(!c.drive()); CHECK_EQ(c.odometer(), 0); }
TEST("drives once started") { Car c{}; c.turnKey(); CHECK(c.drive()); CHECK(c.drive()); CHECK_EQ(c.odometer(), 20); }
TEST("parking stops the engine") { Car c{}; c.turnKey(); c.drive(); c.park(); CHECK(!c.drive()); CHECK_EQ(c.odometer(), 10); }
TEST("each car has its own engine") { Car a{}, b{}; a.turnKey(); CHECK(a.drive()); CHECK(!b.drive()); }

